'use strict'

const { createRequire } = require('node:module')
const ospath = require('node:path')
const vm = require('node:vm')

function requireFromString (code, filename, parent) {
  if (!ospath.isAbsolute(filename)) filename = ospath.resolve(filename)
  const dirname = ospath.dirname(filename)
  const module_ = { id: filename, path: dirname, exports: {}, filename }
  Object.defineProperty(module_, 'parent', { value: parent })
  const iife = '(function (exports, require, module, __filename, __dirname) {\n' + code + '\n})'
  const script = new vm.Script(iife, { filename })
  script.runInThisContext()(module_.exports, createRequire(filename), module_, filename, dirname)
  return module_.exports
}

module.exports = requireFromString
